import{_ as e,o as s,c as o,a4 as p}from"./chunks/framework.DzJZdBQK.js";const a="/assets/image-20260404221920910.-rb96sjG.png",r="/assets/image-20260404222447210.zgrjBbtB.png",i="/assets/image-20260404222544000.Gdn2EL_5.png",c="/assets/image-20260404222624817.Bdbtu4XS.png",f=JSON.parse('{"title":"微前端","description":"","frontmatter":{"date":"2026-04-04T22:09:54","title":"微前端","categories":["AI","微前端"],"tags":["AI","微前端"]},"headers":[],"relativePath":"posts/course100/055.md","filePath":"posts/course100/055.md"}'),l={name:"posts/course100/055.md"};function n(_,t,m,g,u,d){return s(),o("div",null,[...t[0]||(t[0]=[p('<p>之前看到京东微前端框架 MicroApp 的时候，就觉得这个东西挺有意思的，可以和后端的微服务，或者插件系统对接起来用。</p><p>MicroApp 官网是这么介绍微前端的（<a href="https://jd-opensource.github.io/micro-app/docs.html#/%EF%BC%89" target="_blank" rel="noreferrer">https://jd-opensource.github.io/micro-app/docs.html#/）</a></p><blockquote><p>微前端的概念是由 ThoughtWorks 在2016年提出的，它借鉴了微服务的架构理念，核心在于将一个庞大的前端应用拆分成多个独立灵活的小型应用，每个应用都可以独立开发、独立运行、独立部署，再将这些小型应用融合为一个完整的应用，或者将原本运行已久、没有关联的几个应用融合为一个应用。微前端既可以将多个项目融合为一，又可以减少项目之间的耦合，提升项目扩展性，相比一整块的前端仓库，微前端架构下的前端仓库倾向于更小更灵活。 它主要解决了两个问题： 1、随着项目迭代应用越来越庞大，难以维护。 2、跨团队或跨部门协作开发项目导致效率低下的问题。</p></blockquote><p>虽然也尝试过几次，但效果都不理想，毕竟自己不会前端，很多布局类的东西就弄不出来，于是就没再搞了。这次让 AI 重新设计的时候，他是这么回答的，我感觉有戏了。</p><p><img src="'+a+'" alt="image-20260404221920910"></p><p>于是让他不停的改，在耗光一周的 Token 限额的时候，总算有想要的效果了。主应用和子应用都是基于 Soybean Admin 进行修改的。</p><ul><li>主应用</li></ul><p><img src="'+r+'" alt="image-20260404222447210"></p><ul><li>子应用模板</li></ul><p><img src="'+i+'" alt="image-20260404222544000"></p><ul><li>系统管理</li></ul><p><img src="'+c+'" alt="image-20260404222624817"></p>',12)])])}const b=e(l,[["render",n]]);export{f as __pageData,b as default};
